const PARTNERSHIPS_CSS=":root{--bg:#F7FAF8;--paper:#fff;--ink:#142E29;--muted:#516660;--soft:#55667A;--line:#DCE4EA;--accent:#087B58;--accent-dark:#066748;--accent-lite:#E6F4EE;--rail:#182C35;--rail2:#203643;--green:#1E7A4F;--amber:#8A5A0E;--red:#B42335}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}
:focus-visible{outline:3px solid #3FA37E;outline-offset:2px}
.pt-shell{display:grid;grid-template-columns:224px minmax(0,1fr);min-height:760px;background:var(--bg)}
.pt-rail{background:var(--rail);color:#EEF3F6;padding:22px 12px;display:flex;flex-direction:column;gap:18px;min-width:0}
.pt-brand{display:flex;flex-direction:column;padding:0 10px 14px;border-bottom:1px solid #2F4753}.pt-brand strong{font-size:17px;letter-spacing:-.2px}.pt-brand span{font-size:12px;color:#BFCDD5}
.pt-nav{display:flex;flex-direction:column;gap:3px}.pt-nav button{display:flex;align-items:center;gap:10px;width:100%;border:0;border-radius:9px;background:transparent;color:#D2DDE3;padding:10px 11px;text-align:left;font-size:14px;font-weight:560;min-height:42px}.pt-nav button:hover{background:var(--rail2);color:#fff}.pt-nav button[aria-current="page"]{background:#087B58;color:#fff;font-weight:700}.pt-ico{display:flex;width:18px;height:18px;flex:none}
.pt-rail-foot{margin-top:auto;font-size:12px;color:#BFCDD5;padding:12px 10px;border-top:1px solid #2F4753;line-height:1.6}
.pt-main{min-width:0;padding:26px clamp(16px,3vw,36px) 48px;max-width:1440px;width:100%;margin:0 auto}
.pt-top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:18px}.pt-eyebrow{font-size:12px;font-weight:700;color:var(--accent);letter-spacing:.4px;margin-bottom:4px}.pt-title{margin:0;font-size:31px;line-height:1.2;letter-spacing:-.6px;font-weight:760}.pt-subtitle{margin:6px 0 0;color:var(--muted);font-size:14px;max-width:760px}.pt-top-right{display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:flex-end}
.pt-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid #C9D5DF;background:#fff;color:#1D3A33;border-radius:9px;padding:9px 14px;font-size:14px;font-weight:620;min-height:40px;white-space:nowrap}.pt-btn:hover{border-color:#8FA6BA}.pt-btn.small{min-height:34px;padding:6px 11px;font-size:13px}.pt-btn-primary{background:var(--accent);border-color:var(--accent);color:#fff}.pt-btn-primary:hover{background:var(--accent-dark);border-color:var(--accent-dark)}.pt-btn.danger{color:var(--red);border-color:#E8C3C9}
.pt-icon-btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid #C9D5DF;background:#fff;color:#1D3A33;border-radius:9px;width:40px;height:40px;padding:0}.pt-icon-btn:hover{border-color:var(--accent);color:var(--accent)}
.pt-linkbtn{border:0;background:none;color:var(--accent-dark);font-weight:650;padding:0;text-decoration:underline;text-underline-offset:2px;min-height:24px;text-align:left}
.pt-pill{display:inline-flex;align-items:center;border-radius:999px;background:#EEF2F5;color:#3B4D5E;padding:3px 10px;font-size:12px;font-weight:650;white-space:nowrap}.pt-pill.blue{background:var(--accent-lite);color:#066748}.pt-pill.green{background:#E6F4EC;color:#185F3E}.pt-pill.amber{background:#FDF1DC;color:#7A4F0C}.pt-pill.red{background:#FBE8EB;color:#9B1C2E}
.pt-banner{border:1px solid #D5E3EF;background:#EEF7F2;color:#1F3D57;border-radius:10px;padding:11px 14px;margin:0 0 14px;font-size:13px}.pt-banner.ok{background:#EAF6EF;border-color:#C9E6D5;color:#185F3E}.pt-banner.bad{background:#FDF0F2;border-color:#F0C9D0;color:#8E1D2E}.pt-banner.warn{background:#FFF7E8;border-color:#F0DDB4;color:#6B460B}.pt-notice{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
.pt-hero{background:linear-gradient(120deg,#14262A,#182C35 60%,#203643);color:#fff;border-radius:16px;padding:24px 28px;margin-bottom:16px}.pt-hero-over{font-size:12px;letter-spacing:.5px;text-transform:uppercase;color:#C3D0D8;font-weight:650}.pt-hero-sentence{font-size:25px;line-height:1.3;font-weight:700;letter-spacing:-.4px;margin:10px 0 12px;max-width:900px}
.pt-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.pt-kpi{background:#fff;border:1px solid var(--line);border-radius:13px;padding:16px 18px;min-width:0}.pt-kpi-label{font-size:13px;color:var(--muted);font-weight:620}.pt-kpi-value{font-size:28px;font-weight:760;letter-spacing:-.5px;margin:4px 0 2px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.pt-kpi-foot{font-size:12px;color:var(--soft)}.pt-kpi.bad .pt-kpi-value{color:var(--red)}
.pt-panel{background:#fff;border:1px solid var(--line);border-radius:14px;margin-bottom:16px;min-width:0;overflow:hidden}.pt-pad{padding:20px}.pt-panel h2{margin:0;font-size:19px;letter-spacing:-.2px}.pt-panel-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:14px;flex-wrap:wrap}.pt-panel-head p{margin:3px 0 0;color:var(--muted);font-size:13px;max-width:760px}.pt-h3{font-size:15px;margin:16px 0 8px}
.pt-grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.pt-grid2>.pt-panel{margin-bottom:16px}
.pt-scroll{overflow-x:auto;max-width:100%}.pt-table{width:100%;border-collapse:collapse;min-width:640px;font-size:14px}.pt-table caption{text-align:left;font-size:13px;color:var(--muted);padding:6px 14px}.pt-table th,.pt-table td{padding:10px 14px;border-bottom:1px solid #E8EEF2;text-align:left;vertical-align:top}.pt-table thead th{background:#F7FAFC;color:#3F5264;font-size:12px;font-weight:700;white-space:nowrap}.pt-table tbody th{font-weight:620;color:#1D3A33}.pt-table tbody tr:last-child td,.pt-table tbody tr:last-child th{border-bottom:0}.pt-table.compact th,.pt-table.compact td{padding:8px 12px;font-size:13px}.pt-table .num,.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.neg{color:var(--red)}.pos{color:var(--green)}.pt-table tr.total th,.pt-table tr.total td{font-weight:760;border-top:2px solid var(--line);background:#F7FAFC}.pt-sub{display:block;color:var(--soft);font-size:12px;font-weight:400}
.pt-actions{text-align:right;white-space:nowrap;width:1%}.pt-actions .pt-btn{margin-left:4px}.pt-list li .pt-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:4px;white-space:normal;width:auto}.pt-list li .pt-actions .pt-btn{margin:0}.pt-list li>span:first-child{min-width:0;overflow-wrap:anywhere}
.pt-btn{max-width:100%}.pt-btn.small{white-space:normal}
.pt-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 16px;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}.pt-pager{display:inline-flex;align-items:center;gap:8px}
.pt-toolbar{display:flex;gap:9px;align-items:center;min-width:0;flex-wrap:nowrap}.pt-search{flex:1 1 180px;min-width:80px;border:1px solid #C9D5DF;border-radius:9px;padding:9px 12px;min-height:40px;background:#fff}.pt-toolbar .pt-btn{flex:none}
.pt-field{display:flex;flex-direction:column;gap:5px;font-size:13px;color:#33475A;font-weight:620;min-width:0}.pt-field.inline{flex-direction:row;align-items:center;gap:8px}.pt-field.wide{grid-column:1/-1}.pt-input,.pt-textarea,.pt-field select,.pt-field input{border:1px solid #C9D5DF;border-radius:8px;padding:9px 11px;background:#fff;min-height:40px;width:100%;min-width:0;font-weight:400;color:var(--ink)}.pt-field.inline select{width:auto;max-width:320px}.pt-textarea{min-height:96px;resize:vertical}.pt-textarea.tall{min-height:180px}.pt-textarea.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px}
.pt-check{display:inline-flex;align-items:center;gap:8px;font-size:14px;min-height:40px;font-weight:400;color:var(--ink)}.pt-check input{width:18px;height:18px;min-height:0;accent-color:var(--accent);flex:none}.pt-checks{display:flex;flex-direction:column;gap:2px;margin:6px 0 10px}
.pt-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:12px}.pt-row.end{justify-content:flex-end}.pt-row.top0{margin-top:0}
.pt-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.pt-form .pt-row{grid-column:1/-1;margin-top:0}
.pt-list{list-style:none;margin:0;padding:0}.pt-list li{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid #EEF2F5;font-size:14px}.pt-list li:last-child{border-bottom:0}.pt-list.plain li{display:block}.pt-list.pad{padding:0 20px 12px}
.pt-kv{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #EEF2F5;font-size:14px}.pt-kv span{color:var(--muted)}.pt-kv strong{text-align:right;overflow-wrap:anywhere}
.pt-empty{text-align:center;border:1px dashed #C9D5DF;border-radius:12px;padding:28px;color:var(--muted);background:#FBFDFE}.pt-empty strong{display:block;color:var(--ink);font-size:16px;margin-bottom:4px}.pt-none{padding:18px 20px;color:var(--muted);font-size:14px}.pt-muted{color:var(--muted);font-size:13px}
.pt-overlay{position:fixed;inset:0;z-index:30;background:#0E1C2A66;display:flex;justify-content:flex-end;align-items:flex-start;overflow-y:auto}.pt-overlay.center{justify-content:center;align-items:center;padding:16px}
.pt-drawer{width:min(600px,100%);min-height:100%;background:#fff;display:flex;flex-direction:column;box-shadow:-16px 0 40px #0E1C2A33}.pt-drawer.wide{width:min(820px,100%)}.pt-drawer-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding:18px 22px;border-bottom:1px solid var(--line)}.pt-drawer-head h2{margin:0;font-size:21px}.pt-drawer-form{display:flex;flex-direction:column;flex:1}.pt-drawer-body{flex:1;padding:18px 22px;display:flex;flex-direction:column;gap:12px}.pt-drawer-foot{display:flex;justify-content:flex-end;align-items:center;gap:8px;padding:14px 22px;border-top:1px solid var(--line);flex-wrap:wrap}.pt-drawer-foot .pt-muted{margin-right:auto}
.pt-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.pt-foot{font-size:12px;color:var(--soft);margin-top:20px}
.pt-picker{display:flex;flex-wrap:wrap;gap:10px 16px;align-items:flex-end;background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin-bottom:16px}.pt-picker .pt-field{flex:1 1 260px}.pt-picker-meta{display:flex;flex-wrap:wrap;gap:6px;align-items:center;min-height:40px}
.pt-stepper{list-style:none;display:flex;gap:6px;margin:0 0 14px;padding:0;overflow-x:auto}.pt-step{flex:1 0 96px;border-top:4px solid #D5DEE6;padding:8px 6px 0;font-size:12px;color:var(--muted);min-width:0}.pt-step b{display:block;font-size:13px;color:#3F5264}.pt-step.done{border-top-color:#7FA8CE}.pt-step.now{border-top-color:var(--accent)}.pt-step.now b{color:var(--accent-dark)}.pt-step.skip{opacity:.55}
.pt-next{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;background:var(--accent-lite);border:1px solid #BFE0D1;border-radius:10px;padding:12px 14px;font-size:14px}
.pt-chips{display:flex;flex-wrap:wrap;gap:5px}
.pt-thread{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}.pt-msg{border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:14px;max-width:92%;overflow-wrap:anywhere;white-space:pre-wrap}.pt-msg.them{background:#F7FAFC;align-self:flex-start}.pt-msg.us{background:var(--accent-lite);border-color:#BFE0D1;align-self:flex-end}.pt-msg.clar{background:#FFF9EC;border-color:#F0DDB4;max-width:100%}.pt-msg-meta{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center;font-size:12px;color:var(--soft);margin-bottom:4px;white-space:normal}
.pt-mail{border:1px solid var(--line);border-radius:10px;margin-top:10px;overflow:hidden}.pt-mail-head{background:#F7FAFC;padding:8px 12px;font-size:13px;display:flex;flex-wrap:wrap;gap:4px 14px;border-bottom:1px solid var(--line)}.pt-mail pre{margin:0;padding:12px;font:13px/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:#1D3A33}
.pt-report{white-space:pre-wrap;font-size:14px;color:#22313F;background:#FAFCFE;border:1px solid var(--line);border-radius:10px;padding:14px 16px;overflow-wrap:anywhere}
.pt-dev{display:block;font-size:12px}.pt-flag{display:inline-block;margin-top:2px;font-size:12px;color:#7A4F0C;background:#FDF1DC;border-radius:6px;padding:1px 6px;white-space:normal}

.pt-supplier{border:1px solid var(--line);border-radius:12px;padding:14px 16px;margin:0 20px 12px}.pt-supplier-head{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:6px}.pt-supplier h3{margin:0;font-size:16px}
.pt-field small{font-weight:400}
.pt-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@media(max-width:1100px){.pt-shell{grid-template-columns:64px minmax(0,1fr)}.pt-brand span,.pt-nav-label,.pt-rail-foot{display:none}.pt-brand{padding:0 0 12px;align-items:center}.pt-brand strong{font-size:11px;text-align:center}.pt-nav button{justify-content:center;padding:10px 6px}.pt-grid2{grid-template-columns:minmax(0,1fr)}.pt-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:720px){.pt-shell{display:block}.pt-rail{padding:10px 12px;gap:8px;position:static}.pt-brand{display:none}.pt-nav{flex-direction:row;overflow-x:auto;gap:4px}.pt-nav button{width:auto;min-width:44px;justify-content:center;padding:10px}.pt-main{padding:18px 16px 40px}.pt-top{flex-direction:column}.pt-top-right{justify-content:flex-start}.pt-title{font-size:26px}.pt-hero{padding:20px}.pt-hero-sentence{font-size:20px}.pt-kpis{grid-template-columns:minmax(0,1fr)}.pt-kpi-value{font-size:24px}.pt-pair,.pt-form{grid-template-columns:minmax(0,1fr)}.pt-pad{padding:16px}.pt-hide-xs{display:none}.pt-field.inline{flex-direction:column;align-items:stretch}.pt-field.inline select{width:100%;max-width:none}.pt-actions .pt-btn{margin:2px 0 2px 4px}.pt-supplier{margin:0 12px 12px}.pt-msg{max-width:100%}.pt-drawer-head,.pt-drawer-body,.pt-drawer-foot{padding-left:16px;padding-right:16px}}

/* Partnerships additions */
.pt-picker{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end;margin:0 0 16px}.pt-picker .pt-field{min-width:260px;margin:0}.pt-picker-meta{display:flex;flex-wrap:wrap;gap:6px;padding-bottom:8px}
.pt-steps{list-style:none;margin:0 0 12px;padding:0;display:flex;flex-wrap:wrap;gap:8px}.pt-steps li{padding:6px 12px;border:1px solid var(--line);border-radius:999px;font-size:13px;color:var(--muted);background:#fff}.pt-steps li.done{border-color:#BFE0D1;background:#E6F4EE;color:#185F3E;font-weight:600}.pt-steps li.done::before{content:"✓ "}
.pt-sec{margin-top:18px}.pt-sec-head{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;margin-bottom:8px}.pt-sec-head h3{display:flex;align-items:center;gap:10px;margin:0;font-size:16px}
.pt-num{display:inline-flex;min-width:34px;justify-content:center;padding:2px 8px;border-radius:8px;background:#E6F4EE;color:#185F3E;font-variant-numeric:tabular-nums;font-size:13px;font-weight:700}
.pt-heat{background:#E6F4EE;color:#185F3E;font-weight:700}
.pt-mail{border:1px solid var(--line);border-radius:12px;margin:0 0 12px;background:#fff;overflow:hidden}.pt-mail-head{display:flex;gap:8px;align-items:center;justify-content:space-between;padding:10px 14px;background:#F7FAF8;border-bottom:1px solid var(--line)}.pt-mail-subject{padding:10px 14px 0;font-weight:700}.pt-mail-body{margin:0;padding:8px 14px 14px;white-space:pre-wrap;word-break:break-word;font:13px/1.55 Inter,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;color:var(--ink)}
.pt-quote{margin:0 0 14px;padding:10px 14px;border-left:4px solid #087B58;background:#F7FAF8;border-radius:8px;white-space:pre-wrap}
.pt-preview{margin:10px 0 0;padding-left:18px}.pt-preview li{margin:4px 0}.pt-preview ul{margin:4px 0 8px;padding-left:18px}
.pt-fieldset{border:1px solid var(--line);border-radius:10px;padding:10px 14px;margin:0 0 14px;display:flex;flex-direction:column;gap:6px}.pt-fieldset legend{font-weight:700;padding:0 6px}
.pt-integ{margin-top:18px}.pt-pre{white-space:pre-wrap}.pt-field.grow{flex:1 1 260px}
@media (max-width:720px){.pt-picker .pt-field{min-width:0;width:100%}.pt-sec-head{align-items:flex-start}}
.pt-link{border:0;background:none;padding:0;color:#066748;font-weight:650;text-align:left;text-decoration:underline;text-underline-offset:2px;cursor:pointer;font-size:inherit;min-height:24px}.pt-link:hover{color:#142E29}
.pt-list.plain li{display:block}
.pt-seg{display:inline-flex;flex-wrap:wrap;gap:4px;background:#EEF3F0;border-radius:10px;padding:3px}.pt-seg-btn{border:0;background:transparent;border-radius:8px;padding:7px 12px;font-size:13px;font-weight:620;color:#2C4A41;min-height:34px}.pt-seg-btn[aria-pressed="true"]{background:#fff;color:var(--accent-dark);box-shadow:0 1px 2px #0E1C2A22}
.pt-toolbar .pt-seg{flex:none}.pt-select{border:1px solid #C9D5DF;border-radius:9px;padding:8px 10px;min-height:40px;background:#fff;max-width:200px;min-width:0}
.pt-filters{margin-top:12px}.pt-filters-head{font-weight:650;font-size:13px;color:#33475A}.pt-filter-row{display:flex;flex-wrap:wrap;gap:16px;margin-top:10px}.pt-filter-row .pt-field{flex:1 1 170px;max-width:240px}
.pt-pad-top0{padding-top:0}.pt-pad-bottom0{padding-bottom:0}
.pt-board{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(220px,1fr);gap:12px;overflow-x:auto;padding-bottom:6px;max-width:100%}
.pt-col{background:#F3F7F5;border:1px solid var(--line);border-radius:12px;padding:10px;display:flex;flex-direction:column;gap:8px;min-width:0}.pt-col.closed{background:#F7F8FA}.pt-col h3{margin:0 0 2px;font-size:13px;display:flex;justify-content:space-between;align-items:center;color:#2C4A41}.pt-count{background:#fff;border:1px solid var(--line);border-radius:999px;padding:0 8px;font-size:12px;font-weight:700}
.pt-card{display:flex;flex-direction:column;gap:3px;text-align:left;background:#fff;border:1px solid var(--line);border-radius:10px;padding:10px 11px;font-size:13px;color:var(--ink);min-width:0;overflow-wrap:anywhere}.pt-card:hover{border-color:var(--accent)}.pt-card strong{font-size:14px}.pt-card span{color:var(--muted)}.pt-card-meta{font-size:12px}
.pt-flag{display:inline-block;margin-top:2px;font-size:12px;color:#7A4F0C;background:#FDF1DC;border-radius:6px;padding:1px 6px;white-space:normal;font-weight:600}
.pt-tag{display:inline-flex;border-radius:6px;background:#E6F4EE;color:#185F3E;padding:1px 7px;font-size:12px;font-weight:600}
.pt-funnel{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}.pt-funnel li{display:grid;grid-template-columns:minmax(110px,170px) minmax(0,1fr) auto;gap:10px;align-items:center;font-size:14px}.pt-bar{display:block;height:14px;background:#EEF3F0;border-radius:7px;overflow:hidden}.pt-bar span{display:block;height:100%;background:var(--accent);border-radius:7px;min-width:2px}.pt-funnel-n{font-variant-numeric:tabular-nums;white-space:nowrap}
.pt-code{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;background:#F7FAF8;border:1px solid var(--line);border-radius:8px;padding:10px 12px;margin:6px 0 0;color:#1D3A33}
.pt-signal{align-items:flex-start!important}.pt-signal p{margin:4px 0;font-size:14px}.pt-signal>div:first-child{min-width:0;overflow-wrap:anywhere}
.pt-sub{margin-top:12px;padding-top:10px;border-top:1px solid #EEF2F5}.pt-sub h4{margin:0 0 8px;font-size:14px;color:#2C4A41}
.pt-wide{grid-column:1/-1;flex-basis:100%}.pt-picker .pt-field.inline{flex:0 1 auto}.pt-picker .pt-field.inline select{min-width:130px}
.pt-fieldset .pt-check{min-height:32px}.pt-fieldset.wide{grid-column:1/-1}
.pt-list a,.pt-signal a{color:var(--accent-dark);font-weight:650}
